void OutOfLaneFilter::update_parameters(const validator::Params & params)
{
  params_.max_check_time = params.out_of_lane.time;
  params_.min_value = params.out_of_lane.min_value;
}

OutOfLaneFilter::result_t OutOfLaneFilter::is_feasible(
  const TrajectoryPoints & traj_points, const FilterContext & context)
{
  // Check required context data
  if (
    !context.lanelet_map || !context.odometry || traj_points.empty() ||
    !boundary_departure_checker_) {
    return tl::make_unexpected("Insufficient context data");
  }

  const auto path = convert_to_path_with_lane_id(traj_points, params_.max_check_time);

  // Use boundary departure checker to verify if path will leave lane
  const bool will_leave_lane =
    boundary_departure_checker_->checkPathWillLeaveLane(context.lanelet_map, path);

  // Set metrics as ERROR if the path will leave the lane
  std::vector<MetricReport> metrics{
    autoware_trajectory_validator::build<MetricReport>()
      .validator_name(get_name())
      .validator_category(category())
      .metric_name("check_out_of_lane")
      .metric_value(0.0)
      .level(will_leave_lane ? MetricReport::ERROR : MetricReport::OK)};

  const auto is_feasible = !will_leave_lane;

  return ValidationResult{is_feasible, std::move(metrics)};
}

autoware_internal_planning_msgs::msg::PathWithLaneId convert_to_path_with_lane_id(
  const TrajectoryPoints & traj_points, double max_check_time)
{
  autoware_internal_planning_msgs::msg::PathWithLaneId path;
  path.header.stamp = rclcpp::Clock().now();
  path.header.frame_id = "map";

  for (const auto & traj_point : traj_points) {
    if (rclcpp::Duration(traj_point.time_from_start).seconds() > max_check_time) {
      break;
    }

    autoware_internal_planning_msgs::msg::PathPointWithLaneId path_point;
    path_point.point.pose = traj_point.pose;

    // Set velocity
    const double vel = std::sqrt(
      traj_point.longitudinal_velocity_mps * traj_point.longitudinal_velocity_mps +
      traj_point.lateral_velocity_mps * traj_point.lateral_velocity_mps);
    path_point.point.longitudinal_velocity_mps = vel;
    path_point.point.lateral_velocity_mps = 0.0;
    path_point.point.heading_rate_rps = traj_point.heading_rate_rps;

    // Lane IDs will be empty for this check
    path.points.push_back(path_point);
  }

  return path;
}

bool BoundaryDepartureChecker::checkPathWillLeaveLane(
  const lanelet::LaneletMapPtr lanelet_map_ptr, const PathWithLaneId & path) const
{
  autoware_utils_debug::ScopedTimeTrack st(__func__, *time_keeper_);

  // check if the footprint is not fully contained within the fused lanelets polygon
  const std::vector<LinearRing2d> vehicle_footprints =
    utils::createVehicleFootprints(path, *vehicle_info_ptr_, param_.footprint_extra_margin);
  const auto fused_lanelets_polygon = getFusedLaneletPolygonForPath(lanelet_map_ptr, path);
  if (!fused_lanelets_polygon) return true;
  return !std::all_of(
    vehicle_footprints.begin(), vehicle_footprints.end(),
    [&fused_lanelets_polygon](const auto & footprint) {
      return boost::geometry::within(footprint, fused_lanelets_polygon.value());
    });
}

std::vector<LinearRing2d> createVehicleFootprints(
  const geometry_msgs::msg::PoseWithCovariance & covariance, const TrajectoryPoints & trajectory,
  const autoware::vehicle_info_utils::VehicleInfo & vehicle_info,
  const double footprint_margin_scale)
{
  // Calculate longitudinal and lateral margin based on covariance
  const auto margin = utils::calc_margin_from_covariance(covariance, footprint_margin_scale);

  // Create vehicle footprint in base_link coordinate
  const auto local_vehicle_footprint = vehicle_info.createFootprint(margin.lat_m, margin.lon_m);

  // Create vehicle footprint on each TrajectoryPoint
  std::vector<LinearRing2d> vehicle_footprints;
  for (const auto & p : trajectory) {
    vehicle_footprints.push_back(
      autoware_utils_geometry::transform_vector(
        local_vehicle_footprint, autoware_utils_geometry::pose2transform(p.pose)));
  }

  return vehicle_footprints;
}

FootprintMargin calc_margin_from_covariance(
  const geometry_msgs::msg::PoseWithCovariance & covariance, const double scale)
{
  const auto cov_in_map = covariance.covariance;
  Eigen::Matrix2d cov_xy_map;
  cov_xy_map << cov_in_map[0 * 6 + 0], cov_in_map[0 * 6 + 1], cov_in_map[1 * 6 + 0],
    cov_in_map[1 * 6 + 1];

  const double yaw_vehicle = tf2::getYaw(covariance.pose.orientation);

  // To get a position in a transformed coordinate, rotate the inverse direction
  Eigen::Matrix2d r_map2vehicle;
  r_map2vehicle << std::cos(-yaw_vehicle), -std::sin(-yaw_vehicle), std::sin(-yaw_vehicle),
    std::cos(-yaw_vehicle);
  // Rotate covariance E((X, Y)^t*(X, Y)) = E(R*(x,y)*(x,y)^t*R^t)
  // when Rotate point (X, Y)^t= R*(x, y)^t.
  const Eigen::Matrix2d cov_xy_vehicle = r_map2vehicle * cov_xy_map * r_map2vehicle.transpose();

  // The longitudinal/lateral length is represented
  // in cov_xy_vehicle(0,0), cov_xy_vehicle(1,1) respectively.
  return FootprintMargin{cov_xy_vehicle(0, 0) * scale, cov_xy_vehicle(1, 1) * scale};
}

