LinearRing2d createHullFromFootprints(const std::vector<LinearRing2d> & footprints)
{
  MultiPoint2d combined;
  for (const auto & footprint : footprints) {
    for (const auto & p : footprint) {
      combined.push_back(p);
    }
  }

  LinearRing2d hull;
  boost::geometry::convex_hull(combined, hull);

  return hull;
}

lanelet::BasicPolygon2d to_basic_polygon_2d(const LinearRing2d & footprint_hull)
{
  lanelet::BasicPolygon2d basic_polygon;
  basic_polygon.reserve(footprint_hull.size());
  for (const auto & point : footprint_hull) {
    basic_polygon.emplace_back(point.x(), point.y());
  }
  return basic_polygon;
}

Polygon2d to_polygon_2d(const lanelet::BasicPolygon2d & poly)
{
  autoware_utils_geometry::Polygon2d polygon;
  auto & outer = polygon.outer();

  outer.reserve(poly.size());
  for (const auto & p : poly) {
    outer.emplace_back(p.x(), p.y());
  }
  boost::geometry::correct(polygon);
  return polygon;
}

bool all_acceptable() const
{
  return all_evaluations([](const auto & e) { return e.is_feasible || e.is_shadow_mode; });
}

bool all_evaluations(const std::function<bool(const PluginEvaluation &)> & pred) const
{
  return std::all_of(evaluations.begin(), evaluations.end(), [&](const auto & pair) {
    return std::all_of(pair.second.begin(), pair.second.end(), pred);
  });
}
